{
  "name": "agy-openai-bridge",
  "version": "0.2.3",
  "description": "OpenAI-compatible HTTP/SSE API bridge for Antigravity CLI (agy acp)",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "bin": {
    "agy-openai-bridge": "dist/cli.js"
  },
  "files": [
    "dist",
    "!dist/test.*"
  ],
  "scripts": {
    "build": "rm -rf dist && tsc",
    "start": "node ./dist/cli.js",
    "dev": "tsx ./src/cli.ts",
    "test": "node --test ./dist/test.js",
    "prepublishOnly": "npm run build && npm test"
  },
  "keywords": [
    "antigravity",
    "agy",
    "acp",
    "agent-client-protocol",
    "openai",
    "openai-compatible",
    "bridge",
    "proxy",
    "opencode",
    "roo-code",
    "cline",
    "continue",
    "llm"
  ],
  "author": "Arif Widipratomo <arif.widip@gmail.com>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/arifwidip/agy-openai-bridge.git"
  },
  "homepage": "https://github.com/arifwidip/agy-openai-bridge#readme",
  "bugs": {
    "url": "https://github.com/arifwidip/agy-openai-bridge/issues"
  },
  "engines": {
    "node": ">=20.0.0"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "tsx": "^4.19.2",
    "typescript": "^5.7.2"
  }
}

#!/usr/bin/env node
import { BridgeServer } from "./server.js";
function parseArgs(argv) {
    const config = {
        port: Number(process.env.PORT || 8787),
        host: process.env.HOST || "127.0.0.1",
        defaultCwd: process.env.AGY_CWD || process.cwd(),
        apiKey: process.env.API_KEY || undefined,
        agyBin: process.env.AGY_BIN || "agy",
        includeDefaultCustomizations: process.env.AGY_INCLUDE_CUSTOMIZATIONS === "true",
        maxCachedSessions: Number(process.env.MAX_SESSIONS || 50),
        verbose: process.env.VERBOSE === "true",
    };
    for (let i = 0; i < argv.length; i++) {
        const arg = argv[i];
        if (arg === "--help" || arg === "-h") {
            printHelp();
            process.exit(0);
        }
        else if (arg === "--port" || arg === "-p") {
            config.port = Number(argv[++i]);
        }
        else if (arg === "--host") {
            config.host = argv[++i];
        }
        else if (arg === "--cwd") {
            config.defaultCwd = argv[++i];
        }
        else if (arg === "--api-key") {
            config.apiKey = argv[++i];
        }
        else if (arg === "--agy-bin") {
            config.agyBin = argv[++i];
        }
        else if (arg === "--include-customizations") {
            config.includeDefaultCustomizations = true;
        }
        else if (arg === "--verbose" || arg === "-v") {
            config.verbose = true;
        }
    }
    return config;
}
function printHelp() {
    console.log(`
agy-openai-bridge — OpenAI-compatible API server powered by "agy acp"

Usage:
  agy-openai-bridge [options]

Options:
  -p, --port <number>          Port to listen on (default: 8787 or $PORT)
  --host <address>             Host to bind (default: 127.0.0.1 or $HOST)
  --cwd <path>                 Default workspace directory for -agent mode (default: cwd)
  --api-key <key>              Optional Bearer API key required from clients ($API_KEY)
  --agy-bin <path>             Path to agy binary (default: agy)
  --include-customizations     Load default agy skills/MCPs in ACP sessions (default: false)
  -v, --verbose                Enable verbose ACP JSON-RPC logging
  -h, --help                   Show this help message

Endpoints:
  GET  /v1/models              Lists standard models (<model>) and agentic models (<model>-agent)
  POST /v1/chat/completions    OpenAI-compatible chat completions (streaming & non-streaming)
  GET  /health                 Health check

Per-Request Workspace Override (for -agent models):
  Header:   X-Workspace-Dir: /path/to/repo
  API Key:  Authorization: Bearer cwd=/path/to/repo
`);
}
async function main() {
    const config = parseArgs(process.argv.slice(2));
    const server = new BridgeServer(config);
    const shutdown = async () => {
        console.log("\nShutting down agy-openai-bridge...");
        await server.stop();
        process.exit(0);
    };
    process.on("SIGINT", shutdown);
    process.on("SIGTERM", shutdown);
    console.log("Starting agy acp backend...");
    await server.start();
    console.log(`
🚀 agy-openai-bridge is running!
   Base URL:       http://${config.host}:${config.port}/v1
   Models URL:     http://${config.host}:${config.port}/v1/models
   Chat URL:       http://${config.host}:${config.port}/v1/chat/completions
   Default CWD:    ${config.defaultCwd}
   Mode Selection: Use "<model>" for pure LLM / client tools, or "<model>-agent" for full agy agent mode
`);
}
main().catch((err) => {
    console.error("Failed to start agy-openai-bridge:", err);
    process.exit(1);
});

export { BridgeServer } from "./server.js";
export { AcpClient, } from "./acp-client.js";
export { SessionManager } from "./session-manager.js";
export { ToolStreamParser, buildSystemPromptAppend, formatAgentInternalToolUpdate, } from "./tool-bridge.js";
export * from "./types.js";

import * as http from "node:http";
import * as crypto from "node:crypto";
import * as fs from "node:fs";
import { AcpClient } from "./acp-client.js";
import { SessionManager } from "./session-manager.js";
import { buildSystemPromptAppend, formatAgentInternalToolUpdate, ToolStreamParser, } from "./tool-bridge.js";
const DEFAULT_FALLBACK_MODEL = "gemini-4-argon-high";
export class BridgeServer {
    config;
    acp;
    sessions;
    server;
    constructor(config) {
        this.config = config;
        this.acp = new AcpClient(config.agyBin, config.includeDefaultCustomizations, config.defaultCwd, config.verbose);
        this.sessions = new SessionManager(this.acp, config.maxCachedSessions);
        this.server = http.createServer((req, res) => {
            this.handleRequest(req, res).catch((err) => {
                console.error("[bridge-server] Unhandled error:", err);
                if (!res.headersSent) {
                    this.sendJson(res, 500, {
                        error: {
                            message: err instanceof Error ? err.message : String(err),
                            type: "server_error",
                            code: "internal_error",
                        },
                    });
                }
            });
        });
    }
    async start() {
        await this.acp.ensureStarted();
        // Pre-warm standby session in background for immediate Turn-1 readiness
        this.acp
            .getFastestLowModel()
            .then((fastModel) => {
            this.sessions.triggerReplenishStandby({
                baseModelId: fastModel,
                isAgentMode: false,
                cwd: this.config.defaultCwd,
                systemPromptAppend: "",
                systemHash: this.sessions.hashObject({
                    baseModelId: fastModel,
                    isAgentMode: false,
                    cwd: this.config.defaultCwd,
                    systemPromptAppend: "",
                }),
            });
        })
            .catch(() => { });
        return new Promise((resolve) => {
            this.server.listen(this.config.port, this.config.host, () => {
                resolve();
            });
        });
    }
    async stop() {
        this.acp.shutdown();
        return new Promise((resolve) => {
            this.server.close(() => resolve());
        });
    }
    async handleRequest(req, res) {
        // Enable CORS for browser-based OpenAI clients
        res.setHeader("Access-Control-Allow-Origin", "*");
        res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
        res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization, X-Workspace-Dir");
        if (req.method === "OPTIONS") {
            res.writeHead(204);
            res.end();
            return;
        }
        const authCheck = this.checkAuthAndExtractCwd(req);
        if (!authCheck.authorized) {
            this.sendJson(res, 401, {
                error: {
                    message: "Invalid API key",
                    type: "invalid_request_error",
                    code: "invalid_api_key",
                },
            });
            return;
        }
        const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);
        const pathname = url.pathname;
        if (req.method === "GET" && pathname === "/health") {
            this.sendJson(res, 200, {
                status: "ok",
                defaultCwd: this.config.defaultCwd,
            });
            return;
        }
        if (req.method === "GET" &&
            (pathname === "/v1/models" || pathname === "/models")) {
            await this.handleListModels(res);
            return;
        }
        if (req.method === "POST" &&
            (pathname === "/v1/chat/completions" || pathname === "/chat/completions")) {
            const bodyStr = await this.readBody(req);
            let payload;
            try {
                payload = JSON.parse(bodyStr);
            }
            catch {
                this.sendJson(res, 400, {
                    error: {
                        message: "Invalid JSON request body",
                        type: "invalid_request_error",
                        code: "invalid_json",
                    },
                });
                return;
            }
            await this.handleChatCompletions(req, res, payload, authCheck.cwd);
            return;
        }
        this.sendJson(res, 404, {
            error: {
                message: `Unknown endpoint: ${req.method} ${pathname}`,
                type: "invalid_request_error",
                code: "not_found",
            },
        });
    }
    async handleListModels(res) {
        const models = await this.acp.getAvailableModels();
        const created = Math.floor(Date.now() / 1000);
        const data = [];
        for (const m of models) {
            data.push({
                id: m.modelId,
                object: "model",
                created,
                owned_by: "antigravity",
                description: `${m.name} (Standard LLM / Client-Tools Mode)`,
            });
            data.push({
                id: `${m.modelId}-agent`,
                object: "model",
                created,
                owned_by: "antigravity-agent",
                description: `${m.name} (Full Antigravity Agent Mode with Workspace/MCP Tools)`,
            });
        }
        this.sendJson(res, 200, {
            object: "list",
            data,
        });
    }
    async handleChatCompletions(req, res, body, resolvedCwd) {
        if (!Array.isArray(body.messages) || body.messages.length === 0) {
            this.sendJson(res, 400, {
                error: {
                    message: "'messages' must be a non-empty array",
                    type: "invalid_request_error",
                    code: "invalid_messages",
                },
            });
            return;
        }
        const { baseModelId, isAgentMode, responseModelId } = await this.resolveModel(body.model);
        const systemMessages = [];
        const nonSystemMessages = [];
        for (const msg of body.messages) {
            if (msg.role === "system" || msg.role === "developer") {
                if (typeof msg.content === "string" && msg.content.trim()) {
                    systemMessages.push(msg.content);
                }
                else if (Array.isArray(msg.content)) {
                    const joined = msg.content
                        .map((c) => (c.type === "text" ? c.text : ""))
                        .filter(Boolean)
                        .join("\n");
                    if (joined.trim())
                        systemMessages.push(joined);
                }
            }
            else {
                nonSystemMessages.push(msg);
            }
        }
        const isUtility = this.isUtilityPrompt(body);
        const hasClientTools = !isUtility &&
            !isAgentMode &&
            Array.isArray(body.tools) &&
            body.tools.length > 0 &&
            body.tool_choice !== "none";
        const systemPromptAppend = isUtility
            ? ""
            : buildSystemPromptAppend(body, systemMessages, isAgentMode);
        const acquired = isUtility
            ? await this.sessions.acquireUtilitySession({
                cwd: resolvedCwd,
                messages: nonSystemMessages,
                systemInstructions: systemMessages.join("\n"),
            })
            : await this.sessions.acquireSession({
                baseModelId,
                isAgentMode,
                cwd: resolvedCwd,
                systemPromptAppend,
                nonSystemMessages,
            });
        const completionId = `chatcmpl-${crypto.randomBytes(12).toString("hex")}`;
        const created = Math.floor(Date.now() / 1000);
        const toolParser = new ToolStreamParser(hasClientTools);
        if (body.stream) {
            await this.streamChatCompletion(req, res, body, acquired, completionId, created, responseModelId, isAgentMode, toolParser);
        }
        else {
            await this.nonStreamChatCompletion(req, res, acquired, completionId, created, responseModelId, isAgentMode, toolParser);
        }
    }
    async streamChatCompletion(req, res, body, acquired, completionId, created, responseModelId, isAgentMode, toolParser) {
        res.writeHead(200, {
            "Content-Type": "text/event-stream; charset=utf-8",
            "Cache-Control": "no-cache, no-transform",
            Connection: "keep-alive",
            "X-Accel-Buffering": "no",
            "X-Agy-Session-Id": acquired.sessionId,
            "X-Agy-Session-Reused": acquired.reused ? "true" : "false",
        });
        let clientAborted = false;
        res.on("close", () => {
            if (!res.writableEnded) {
                clientAborted = true;
                this.acp.cancelSession(acquired.sessionId).catch(() => { });
            }
        });
        const writeChunk = (delta, finishReason = null, usage) => {
            if (clientAborted || res.writableEnded)
                return;
            const chunkObj = {
                id: completionId,
                object: "chat.completion.chunk",
                created,
                model: responseModelId,
                choices: [
                    {
                        index: 0,
                        delta,
                        finish_reason: finishReason,
                    },
                ],
            };
            if (usage) {
                chunkObj.usage = usage;
            }
            res.write(`data: ${JSON.stringify(chunkObj)}\n\n`);
        };
        // Send initial role chunk
        writeChunk({ role: "assistant", content: "" });
        let fullAssistantText = "";
        const allToolCalls = [];
        const emitParsedStep = (step) => {
            if (step.textDelta) {
                fullAssistantText += step.textDelta;
                writeChunk({ content: step.textDelta });
            }
            for (const tc of step.toolCalls) {
                allToolCalls.push(tc);
            }
            for (const delta of step.toolCallDeltas) {
                writeChunk({
                    tool_calls: [
                        {
                            index: delta.index,
                            ...(delta.id ? { id: delta.id, type: "function" } : {}),
                            function: {
                                ...(delta.function?.name ? { name: delta.function.name } : {}),
                                ...(delta.function?.arguments !== undefined
                                    ? { arguments: delta.function.arguments }
                                    : {}),
                            },
                        },
                    ],
                });
            }
        };
        try {
            const promptResult = await this.acp.prompt(acquired.sessionId, acquired.promptBlocks, (update) => {
                if (clientAborted)
                    return;
                if (update.sessionUpdate === "agent_thought_chunk") {
                    const thoughtText = this.extractUpdateText(update);
                    if (thoughtText) {
                        writeChunk({ reasoning_content: thoughtText });
                    }
                    return;
                }
                if (isAgentMode &&
                    (update.sessionUpdate === "tool_call" ||
                        update.sessionUpdate === "tool_call_update")) {
                    const formatted = formatAgentInternalToolUpdate(update);
                    if (formatted) {
                        writeChunk({ reasoning_content: formatted });
                    }
                    return;
                }
                if (update.sessionUpdate === "agent_message_chunk") {
                    const textChunk = this.extractUpdateText(update);
                    if (textChunk) {
                        const step = toolParser.push(textChunk);
                        emitParsedStep(step);
                    }
                }
            });
            const flushed = toolParser.flush();
            emitParsedStep(flushed);
            acquired.finalizeTurn(fullAssistantText, allToolCalls);
            const finishReason = allToolCalls.length > 0 ? "tool_calls" : "stop";
            const usagePayload = this.formatOpenAIUsage(promptResult.usage);
            if (body.stream_options?.include_usage && usagePayload) {
                writeChunk({}, finishReason);
                if (!clientAborted && !res.writableEnded) {
                    res.write(`data: ${JSON.stringify({
                        id: completionId,
                        object: "chat.completion.chunk",
                        created,
                        model: responseModelId,
                        choices: [],
                        usage: usagePayload,
                    })}\n\n`);
                }
            }
            else {
                writeChunk({}, finishReason, usagePayload);
            }
            if (!clientAborted && !res.writableEnded) {
                res.write("data: [DONE]\n\n");
                res.end();
            }
        }
        catch (err) {
            await acquired.releaseOnError();
            if (!clientAborted && !res.writableEnded) {
                writeChunk({
                    content: `\n[Bridge Error: ${err instanceof Error ? err.message : String(err)}]`,
                }, "stop");
                res.write("data: [DONE]\n\n");
                res.end();
            }
        }
    }
    async nonStreamChatCompletion(req, res, acquired, completionId, created, responseModelId, isAgentMode, toolParser) {
        let fullAssistantText = "";
        let fullReasoningText = "";
        const allToolCalls = [];
        res.on("close", () => {
            if (!res.writableEnded) {
                this.acp.cancelSession(acquired.sessionId).catch(() => { });
            }
        });
        try {
            const promptResult = await this.acp.prompt(acquired.sessionId, acquired.promptBlocks, (update) => {
                if (update.sessionUpdate === "agent_thought_chunk") {
                    fullReasoningText += this.extractUpdateText(update);
                    return;
                }
                if (isAgentMode &&
                    (update.sessionUpdate === "tool_call" ||
                        update.sessionUpdate === "tool_call_update")) {
                    const formatted = formatAgentInternalToolUpdate(update);
                    if (formatted) {
                        fullReasoningText += formatted;
                    }
                    return;
                }
                if (update.sessionUpdate === "agent_message_chunk") {
                    const textChunk = this.extractUpdateText(update);
                    if (textChunk) {
                        const step = toolParser.push(textChunk);
                        fullAssistantText += step.textDelta;
                        allToolCalls.push(...step.toolCalls);
                    }
                }
            });
            const flushed = toolParser.flush();
            fullAssistantText += flushed.textDelta;
            allToolCalls.push(...flushed.toolCalls);
            acquired.finalizeTurn(fullAssistantText, allToolCalls);
            const messageObj = {
                role: "assistant",
                content: allToolCalls.length > 0 && !fullAssistantText
                    ? null
                    : fullAssistantText,
            };
            if (fullReasoningText) {
                messageObj.reasoning_content = fullReasoningText;
            }
            if (allToolCalls.length > 0) {
                messageObj.tool_calls = allToolCalls;
            }
            const finishReason = allToolCalls.length > 0 ? "tool_calls" : "stop";
            res.setHeader("X-Agy-Session-Id", acquired.sessionId);
            res.setHeader("X-Agy-Session-Reused", acquired.reused ? "true" : "false");
            this.sendJson(res, 200, {
                id: completionId,
                object: "chat.completion",
                created,
                model: responseModelId,
                choices: [
                    {
                        index: 0,
                        message: messageObj,
                        finish_reason: finishReason,
                    },
                ],
                usage: this.formatOpenAIUsage(promptResult.usage) ?? {
                    prompt_tokens: 0,
                    completion_tokens: 0,
                    total_tokens: 0,
                },
            });
        }
        catch (err) {
            await acquired.releaseOnError();
            this.sendJson(res, 500, {
                error: {
                    message: err instanceof Error ? err.message : String(err),
                    type: "server_error",
                    code: "acp_prompt_error",
                },
            });
        }
    }
    extractUpdateText(update) {
        if (!update.content)
            return "";
        if (!Array.isArray(update.content)) {
            return update.content.text ?? "";
        }
        return update.content
            .map((item) => item.content?.text ?? "")
            .join("");
    }
    formatOpenAIUsage(usage) {
        if (!usage)
            return undefined;
        const promptTokens = usage.inputTokens ?? 0;
        const completionTokens = (usage.outputTokens ?? 0) + (usage.thoughtTokens ?? 0);
        const totalTokens = usage.totalTokens ?? promptTokens + completionTokens;
        return {
            prompt_tokens: promptTokens,
            completion_tokens: completionTokens,
            total_tokens: totalTokens,
            ...(usage.thoughtTokens !== undefined
                ? {
                    completion_tokens_details: {
                        reasoning_tokens: usage.thoughtTokens,
                    },
                }
                : {}),
        };
    }
    async resolveModel(requestedModel) {
        const raw = (requestedModel || DEFAULT_FALLBACK_MODEL).trim();
        const isAgentMode = raw.endsWith("-agent");
        const stripped = isAgentMode ? raw.slice(0, -"-agent".length) : raw;
        const available = await this.acp.getAvailableModels();
        const exact = available.find((m) => m.modelId === stripped);
        if (exact) {
            return {
                baseModelId: exact.modelId,
                isAgentMode,
                responseModelId: raw,
            };
        }
        // Fuzzy/alias match (e.g. "claude-sonnet" or "gpt-4o")
        const lower = stripped.toLowerCase();
        const fuzzy = available.find((m) => m.modelId.toLowerCase().includes(lower));
        if (fuzzy) {
            return {
                baseModelId: fuzzy.modelId,
                isAgentMode,
                responseModelId: isAgentMode
                    ? `${fuzzy.modelId}-agent`
                    : fuzzy.modelId,
            };
        }
        const fallback = available[0]?.modelId ?? DEFAULT_FALLBACK_MODEL;
        return {
            baseModelId: fallback,
            isAgentMode,
            responseModelId: isAgentMode ? `${fallback}-agent` : fallback,
        };
    }
    isUtilityPrompt(body) {
        if (Array.isArray(body.tools) &&
            body.tools.length > 0 &&
            body.tool_choice !== "none") {
            return false;
        }
        if (!Array.isArray(body.messages) || body.messages.length > 3) {
            return false;
        }
        for (const msg of body.messages) {
            if (msg.role === "system" || msg.role === "developer") {
                const text = typeof msg.content === "string"
                    ? msg.content
                    : Array.isArray(msg.content)
                        ? msg.content
                            .map((c) => (c.type === "text" ? c.text : ""))
                            .join(" ")
                        : "";
                if (/title generator|generate a brief title|output only a thread title|brief title that would help/i.test(text)) {
                    return true;
                }
            }
        }
        return false;
    }
    checkAuthAndExtractCwd(req) {
        let cwd = this.config.defaultCwd;
        // 1. Check X-Workspace-Dir header
        const headerCwd = req.headers["x-workspace-dir"];
        if (typeof headerCwd === "string" && headerCwd.trim()) {
            const candidate = headerCwd.trim();
            if (fs.existsSync(candidate)) {
                cwd = candidate;
            }
        }
        // 2. Check Authorization Bearer token (supports `cwd=/path` or `key;cwd=/path`)
        const authHeader = req.headers["authorization"] ?? "";
        const bearer = authHeader.replace(/^Bearer\s+/i, "").trim();
        let providedKey = bearer;
        if (bearer.includes("cwd=")) {
            const parts = bearer.split(/[;,]/);
            const nonCwdParts = [];
            for (const part of parts) {
                const trimmed = part.trim();
                if (trimmed.startsWith("cwd=")) {
                    const candidate = trimmed.slice("cwd=".length).trim();
                    if (candidate && fs.existsSync(candidate)) {
                        cwd = candidate;
                    }
                }
                else if (trimmed) {
                    nonCwdParts.push(trimmed);
                }
            }
            providedKey = nonCwdParts.join(";");
        }
        if (this.config.apiKey && providedKey !== this.config.apiKey) {
            return { authorized: false, cwd };
        }
        return { authorized: true, cwd };
    }
    readBody(req) {
        return new Promise((resolve, reject) => {
            const chunks = [];
            req.on("data", (c) => chunks.push(c));
            req.on("end", () => resolve(Buffer.concat(chunks).toString("utf-8")));
            req.on("error", reject);
        });
    }
    sendJson(res, status, data) {
        const body = JSON.stringify(data, null, 2);
        res.writeHead(status, {
            "Content-Type": "application/json; charset=utf-8",
            "Content-Length": Buffer.byteLength(body),
        });
        res.end(body);
    }
}
